    q1: ["What number mattered most this week?", "أي رقم كان الأهم هذا الأسبوع؟"], q1Hint: ["Pick the one that would have changed a decision if it moved.", "اختر الرقم الذي كان سيغير قرارا لو تحرك."], options1: [["New customers or signups", "عملاء أو تسجيلات جدد"], ["Revenue or pipeline", "الإيراد أو خط المبيعات"], ["Retention or churn", "الاحتفاظ أو التسرب"], ["Team capacity or hiring", "طاقة الفريق أو التوظيف"]],
    q2: ["What changed since last week?", "ما الذي تغير منذ الأسبوع الماضي؟"], q2Hint: ["This is what goes in the note.", "هذا ما يُكتب في الملاحظة."], options2: [["It improved and I know why", "تحسن وأعرف السبب"], ["It improved and I'm not sure why", "تحسن ولست متأكدا من السبب"], ["It got worse and I know why", "ساء وأعرف السبب"], ["It got worse and I'm not sure why", "ساء ولست متأكدا من السبب"]],
    resultTagline: ["Weekly note / ready", "ملاحظة أسبوعية / جاهزة"],
