function GenericToolFlow({ config }: { config: ToolConfig }) {
  const [step, setStep] = useState(0);
  const [result, setResult] = useState(false);
  const [exported, setExported] = useState(false);
  const restart = () => { setStep(0); setResult(false); setExported(false); };
  const exportBrief = () => {
    const brief = [config.briefTitle, "=".repeat(config.briefTitle.length), "", `Signal: ${config.signalTitle}`, config.signalBody, "", `Next: ${config.nextTitle}`, config.nextBody, "", "Generated in the ASaaSI tools prototype."].join("\n");
    const blob = new Blob([brief], { type: "text/markdown;charset=utf-8" });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `asaasi-${config.fileSlug}.md`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => window.URL.revokeObjectURL(url), 1000);
    setExported(true);
  };
  const { t, formatNum } = useLocale();
  const options = step === 0 ? config.options1 : config.options2;
  return <><div className="tool-room-hero"><div><SignalTag tone="soft">{t(...config.tag)}</SignalTag><h1>{t(...config.title)}</h1><p>{t(...config.intro)}</p></div><div className="tool-room-meta"><span className="mono">{t("Estimated time", "الوقت المقدر")}</span><strong>{config.time}</strong><span className="mono">{t("Output", "الناتج")}</span><strong>{t(...config.output)}</strong></div></div><div className="ai-boundary-note"><Sparkles size={15} /><span><strong>{t("What this assistant uses:", "ما يستخدمه هذا المساعد:")}</strong> {t("only the choices in this tool and your current founder stage. Review the draft before sharing it with anyone.", "فقط الخيارات في هذه الأداة ومرحلتك الحالية كمؤسس. راجع المسودة قبل مشاركتها مع أي شخص.")}</span></div><div className="tool-workbench"><div className="tool-progress"><span className={step >= 0 ? "active" : ""}>{t("01 Context", "٠١ السياق")}</span><span className={step >= 1 ? "active" : ""}>{t("02 Signal", "٠٢ الإشارة")}</span><span className={result ? "active" : ""}>{t("03 Brief", "٠٣ الموجز")}</span></div>{result ? <div className="tool-result"><div className="result-heading"><div className="complete-node"><Check size={22} /></div><div><SectionLabel>{t(...config.resultTagline)}</SectionLabel><h2>{t(...config.signalTitle)}</h2></div></div><div className="result-grid"><div><span className="mono">{t("Your signal", "إشارتك")}</span><strong>{t(...config.signalTitle)}</strong><p>{t(...config.signalBody)}</p></div><div><span className="mono">{t("Next move", "الخطوة التالية")}</span><strong>{t(...config.nextTitle)}</strong><p>{t(...config.nextBody)}</p></div></div><div className="result-actions"><button type="button" className="button button-primary" onClick={restart}>{t("Run another brief", "شغّل موجزا آخر")} <ArrowRight size={14} /></button><button type="button" className="button button-ghost" onClick={exportBrief}><Download size={14} /> {exported ? t("Brief exported", "تم تصدير الموجز") : t("Export brief", "صدّر الموجز")}</button><Link href="/requests/new" className="text-link">{t("Ask someone to review it", "اطلب من شخص مراجعته")} <ArrowRight size={14} /></Link></div>{exported && <div className="inline-success" role="status"><Check size={15} /> {t("Brief downloaded as a Markdown file. You can now review it or share it with a founder, coach, or teammate.", "تم تنزيل الموجز كملف Markdown. يمكنك الآن مراجعته أو مشاركته مع مؤسس أو مدرب أو زميل.")}</div>}</div> : <div className="tool-input-grid"><div className="tool-question"><span className="mono">{t("Question", "السؤال")} {formatNum(step + 1)} / {formatNum(2)}</span><h2>{step === 0 ? t(...config.q1) : t(...config.q2)}</h2><p>{step === 0 ? t(...config.q1Hint) : t(...config.q2Hint)}</p>{step > 0 && <button type="button" className="text-link" onClick={() => setStep(0)}><ArrowLeft size={14} /> {t("Change the previous answer", "غيّر الإجابة السابقة")}</button>}</div><div className="tool-options">{options.map((option) => <button type="button" className="tool-option" onClick={() => step === 0 ? setStep(1) : setResult(true)} key={option[0]}><span>{t(...option)}</span><ArrowRight size={15} /></button>)}</div></div>}</div></>;
}

function RunwayToolFlow() {
  const { t } = useLocale();
  const config = TOOL_CONFIGS["survival-calculator"];
  const [cash, setCash] = useState("120000");
  const [burn, setBurn] = useState("18000");
  const [revenue, setRevenue] = useState("6000");
  const [result, setResult] = useState(false);
  const [exported, setExported] = useState(false);
  const cashNum = Number(cash) || 0;
  const burnNum = Number(burn) || 0;
  const revenueNum = Number(revenue) || 0;
  const netBurn = Math.max(0, burnNum - revenueNum);
  const runwayMonths = netBurn > 0 ? Math.floor(cashNum / netBurn) : Infinity;
  const scenarioMonths = netBurn > 0 ? Math.floor(cashNum / Math.max(1, netBurn * 0.85)) : Infinity;
  const restart = () => setResult(false);
  const exportBrief = () => {
    const brief = [
      config.briefTitle, "=".repeat(config.briefTitle.length), "",
      `Cash on hand: $${cashNum.toLocaleString()}`,
      `Monthly burn: $${burnNum.toLocaleString()}`,
      `Monthly revenue: $${revenueNum.toLocaleString()}`,
      `Net burn: $${netBurn.toLocaleString()}/mo`,
      `Runway at current burn: ${runwayMonths === Infinity ? "break-even or profitable" : `${runwayMonths} months`}`,
      `Runway if net burn drops 15%: ${scenarioMonths === Infinity ? "break-even or profitable" : `${scenarioMonths} months`}`,
      "", "Generated in the ASaaSI tools prototype."
    ].join("\n");
    const blob = new Blob([brief], { type: "text/markdown;charset=utf-8" });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = "asaasi-survival-calculator.md";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => window.URL.revokeObjectURL(url), 1000);
    setExported(true);
  };
  return <><div className="tool-room-hero"><div><SignalTag tone="soft">{t(...config.tag)}</SignalTag><h1>{t(...config.title)}</h1><p>{t(...config.intro)}</p></div><div className="tool-room-meta"><span className="mono">{t("Estimated time", "الوقت المقدر")}</span><strong>{config.time}</strong><span className="mono">{t("Output", "الناتج")}</span><strong>{t(...config.output)}</strong></div></div><div className="ai-boundary-note"><Sparkles size={15} /><span><strong>{t("What this calculates:", "ما تحسبه هذه الأداة:")}</strong> {t("cash ÷ net monthly burn. It cannot see one-time costs, funding in progress, or seasonality, treat the range as a starting assumption.", "السيولة ÷ صافي الحرق الشهري. لا يمكنها رؤية التكاليف لمرة واحدة أو التمويل الجاري أو الموسمية، تعامل مع النطاق كافتراض بداية.")}</span></div><div className="tool-workbench"><div className="tool-progress"><span className="active">{t("01 Inputs", "٠١ المدخلات")}</span><span className={result ? "active" : ""}>{t("02 Runway", "٠٢ الاستمرارية")}</span></div>{result ? <div className="tool-result"><div className="result-heading"><div className="complete-node"><Check size={22} /></div><div><SectionLabel>{t(...config.resultTagline)}</SectionLabel><h2>{runwayMonths === Infinity ? t("You're at or near break-even.", "أنت عند نقطة التعادل أو قريب منها.") : t(`About ${runwayMonths} months of runway at this burn.`, `نحو ${runwayMonths} أشهر من الاستمرارية عند هذا المعدل.`)}</h2></div></div><div className="result-grid"><div><span className="mono">{t("Net monthly burn", "صافي الحرق الشهري")}</span><strong>${netBurn.toLocaleString()}/{t("mo", "شهر")}</strong><p>{t("Monthly burn minus monthly revenue, the number that actually eats your cash.", "الحرق الشهري ناقص الإيراد الشهري، الرقم الذي يستهلك سيولتك فعلا.")}</p></div><div><span className="mono">{t("If net burn drops 15%", "إذا انخفض صافي الحرق ١٥٪")}</span><strong>{scenarioMonths === Infinity ? t("Break-even or better", "تعادل أو أفضل") : t(`${scenarioMonths} months`, `${scenarioMonths} أشهر`)}</strong><p>{t("A realistic first scenario before you touch pricing or headcount.", "سيناريو أول واقعي قبل أن تلمس التسعير أو عدد الموظفين.")}</p></div></div><div className="result-actions"><button type="button" className="button button-primary" onClick={restart}>{t("Adjust the inputs", "عدّل المدخلات")} <ArrowRight size={14} /></button><button type="button" className="button button-ghost" onClick={exportBrief}><Download size={14} /> {exported ? t("Brief exported", "تم تصدير الموجز") : t("Export brief", "صدّر الموجز")}</button><Link href="/requests/new" className="text-link">{t("Ask someone to review it", "اطلب من شخص مراجعته")} <ArrowRight size={14} /></Link></div>{exported && <div className="inline-success" role="status"><Check size={15} /> {t("Runway estimate downloaded as a Markdown file.", "تم تنزيل تقدير الاستمرارية كملف Markdown.")}</div>}</div> : <div className="tool-input-grid"><div className="tool-question"><span className="mono">{t("Your numbers", "أرقامك")}</span><h2>{t("Cash, burn, and revenue.", "السيولة، والحرق، والإيراد.")}</h2><p>{t("Monthly figures, in whatever currency you track internally.", "أرقام شهرية، بأي عملة تتابعها داخليا.")}</p></div><form className="tool-options" style={{ display: "grid", gap: 14 }} onSubmit={(event) => { event.preventDefault(); setResult(true); }}><label style={{ display: "grid", gap: 6, textAlign: "left" }}>{t("Cash on hand", "السيولة المتاحة")}<input type="number" min="0" value={cash} onChange={(event) => setCash(event.target.value)} required /></label><label style={{ display: "grid", gap: 6, textAlign: "left" }}>{t("Monthly burn (all costs)", "الحرق الشهري (كل التكاليف)")}<input type="number" min="0" value={burn} onChange={(event) => setBurn(event.target.value)} required /></label><label style={{ display: "grid", gap: 6, textAlign: "left" }}>{t("Monthly revenue", "الإيراد الشهري")}<input type="number" min="0" value={revenue} onChange={(event) => setRevenue(event.target.value)} /></label><button type="submit" className="button button-dark full">{t("Calculate runway", "احسب الاستمرارية")} <ArrowRight size={14} /></button></form></div>}</div></>;
}

export function ToolFlow() {
  const { t } = useLocale();
  const params = useParams<{ slug: string }>();
  const config = TOOL_CONFIGS[params.slug ?? ""];
  if (!config) return <ProductShell title={t("Decision tool", "أداة القرار")} active="/dashboard/coach"><div className="empty-state"><h2>{t("This tool isn't built yet.", "هذه الأداة لم تُبنَ بعد.")}</h2><p>{t("We're adding it to the workbench soon. In the meantime, try the founder diagnostic or the survival calculator.", "سنضيفها إلى طاولة العمل قريبا. في الأثناء، جرب تشخيص المؤسس أو حاسبة الاستمرارية.")}</p><Link href="/tools" className="button button-dark">{t("Back to all tools", "العودة إلى كل الأدوات")} <ArrowRight size={14} /></Link></div></ProductShell>;
  return <ProductShell title={t("Decision tool", "أداة القرار")} active="/dashboard/coach">{params.slug === "survival-calculator" ? <RunwayToolFlow /> : <GenericToolFlow config={config} />}</ProductShell>;
}

export function RecoveryFlow({ mode = "forgot" }: { mode?: "forgot" | "reset" | "verify" }) {
  const { t } = useLocale();
  const [sent, setSent] = useState(false);
  const copy = mode === "forgot" ? { label: t("Recovery / Find your way back", "الاستعادة / اعثر على طريقك"), title: t("The thread is still here.", "الخيط لا يزال هنا."), body: t("Enter your account email and we'll send a calm, time-limited reset link.", "أدخل بريد حسابك وسنرسل رابط إعادة تعيين محدود المدة.") } : mode === "reset" ? { label: t("Recovery / New password", "الاستعادة / كلمة مرور جديدة"), title: t("Choose a stronger next step.", "اختر خطوة تالية أقوى."), body: t("Set a new password, then return to the workspace you were building.", "عيّن كلمة مرور جديدة، ثم عد إلى مساحة العمل التي كنت تبنيها.") } : { label: t("Account / Verify email", "الحساب / تحقق من البريد"), title: t("One small signal before you enter.", "إشارة صغيرة واحدة قبل الدخول."), body: t("Verify your email so introductions, event reminders, and saved work reach the right place.", "تحقق من بريدك الإلكتروني لتصل المقدمات وتذكيرات الفعاليات والعمل المحفوظ إلى المكان الصحيح.") };
  return <div className="account-flow"><div className="account-visual"><SectionLabel light>{copy.label}</SectionLabel><h1>{copy.title}</h1><p>{copy.body}</p><Link href="/login" className="text-link light">{t("Return to log in", "العودة إلى تسجيل الدخول")} <ArrowRight size={14} /></Link></div><div className="account-form-wrap"><Link href="/" className="account-logo"><Logo /></Link><div className="account-form">{sent ? <div className="success-state"><div className="complete-node"><Check size={22} /></div><SectionLabel>{t("Signal sent", "تم إرسال الإشارة")}</SectionLabel><h2>{mode === "verify" ? t("Check your inbox.", "تحقق من بريدك الوارد.") : t("You can close this tab.", "يمكنك إغلاق هذا التبويب.")}</h2><p>{t("We sent the next step to your email. If it does not arrive, check spam or try again.", "أرسلنا الخطوة التالية إلى بريدك. إذا لم تصل، تحقق من الرسائل غير المرغوبة أو حاول مجددا.")}</p><button className="button button-ghost" onClick={() => setSent(false)}>{t("Use another email", "استخدم بريدا آخر")}</button></div> : <><SectionLabel>{copy.label}</SectionLabel><h2>{mode === "forgot" ? t("Reset access.", "أعد تعيين الوصول.") : mode === "reset" ? t("New password.", "كلمة مرور جديدة.") : t("Verify your email.", "تحقق من بريدك الإلكتروني.")}</h2><p>{mode === "reset" ? t("Choose at least 8 characters.", "اختر ٨ أحرف على الأقل.") : t("We'll keep the route short.", "سنبقي المسار قصيرا.")}</p>{mode === "reset" ? <><label>{t("New password", "كلمة مرور جديدة")}<input type="password" placeholder={t("At least 8 characters", "٨ أحرف على الأقل")} /></label><label>{t("Confirm password", "تأكيد كلمة المرور")}<input type="password" placeholder={t("Repeat your password", "أعد كتابة كلمة المرور")} /></label></> : <label>{t("Email", "البريد الإلكتروني")}<input type="email" placeholder="you@company.com" /></label>}<button className="button button-primary full" onClick={() => setSent(true)}>{mode === "forgot" ? t("Send reset link", "أرسل رابط إعادة التعيين") : mode === "reset" ? t("Save new password", "احفظ كلمة المرور الجديدة") : t("Send verification", "أرسل رمز التحقق")} <ArrowRight size={14} /></button></>}</div></div></div>;
}

export function FollowingWorkspace() {
  const { t, formatNum } = useLocale();
  const items = [["Mariam Al-Hadid", "مريم الحداد"], ["Pricing as a system", "التسعير كنظام"], ["SaaS Summit MENA 2026", "قمة برمجيات المنطقة ٢٠٢٦"]] as const;
  const [followed, setFollowed] = useState(items.map(([en]) => en));
  const kindLabel = (index: number) => index === 0 ? t("Person", "شخص") : index === 1 ? t("Idea", "فكرة") : t("Event", "فعالية");
  const noteLabel = (index: number) => index === 0 ? t("New activity: shared a pricing teardown.", "نشاط جديد: شارك تحليل تسعير.") : index === 1 ? t("New note added to your learning path.", "أُضيفت ملاحظة جديدة إلى مسار تعلمك.") : t("Registration opens next week.", "يفتح التسجيل الأسبوع القادم.");
  return <ProductShell title={t("Following", "المتابَعون")} active="/dashboard/following"><div className="product-page-heading compact"><div><SectionLabel>{t("Following / Keep the thread", "المتابَعون / أبقِ الخيط")}</SectionLabel><h1>{t("Return to the people and events that matter.", "عد إلى الأشخاص والفعاليات المهمة.")}</h1><p>{t("Following is for ongoing context. Save is for a single future action.", "المتابعة لسياق مستمر. الحفظ لإجراء واحد مستقبلي.")}</p></div><SignalTag tone="soft">{formatNum(followed.length)} {t("active threads", "خيوط نشطة")}</SignalTag></div><div className="saved-list">{followed.map((itemEn, index) => { const item = items.find(([en]) => en === itemEn) ?? items[0]; return <article className="saved-row" key={itemEn}><span className={`saved-node tone-${index % 3}`} /><div><span className="mono">{kindLabel(index)}</span><h2>{t(item[0], item[1])}</h2><p>{noteLabel(index)}</p></div><button className="button button-ghost" onClick={() => setFollowed(followed.filter((entry) => entry !== itemEn))}>{t("Following", "متابَع")} <Check size={13} /></button></article>; })}</div></ProductShell>;
}

export function InvitationsWorkspace() {
  const { t, formatNum } = useLocale();
  const items = [["Join Atlas Labs workspace", "انضم إلى مساحة عمل Atlas Labs"], ["Review Omar's introduction", "راجع مقدمة عمر"]] as const;
  const [invites, setInvites] = useState(items.map(([en]) => en));
  const [accepted, setAccepted] = useState<string[]>([]);
  return <ProductShell title={t("Invitations", "الدعوات")} active="/dashboard/invitations"><div className="product-page-heading compact"><div><SectionLabel>{t("Invitations", "الدعوات")} / {t(`${invites.length} waiting`, `${formatNum(invites.length)} بانتظار الرد`)}</SectionLabel><h1>{t("Open the right door.", "افتح الباب الصحيح.")}</h1><p>{t("Invitations are small commitments. See the context before you accept.", "الدعوات التزامات صغيرة. اطلع على السياق قبل أن تقبل.")}</p></div></div><div className="saved-list">{invites.map((inviteEn) => { const invite = items.find(([en]) => en === inviteEn) ?? items[0]; return <article className="saved-row" key={inviteEn}><span className="saved-node" /><div><span className="mono">{t("Pending invitation", "دعوة معلقة")}</span><h2>{t(invite[0], invite[1])}</h2><p>{inviteEn.includes("Atlas") ? t("From Sara · shared workspace for SaaS analytics.", "من سارة · مساحة عمل مشتركة لتحليلات البرمجيات.") : t("From Omar · a 20-minute pricing conversation.", "من عمر · محادثة تسعير مدتها ٢٠ دقيقة.")}</p></div>{accepted.includes(inviteEn) ? <SignalTag tone="soft">{t("Accepted", "مقبولة")}</SignalTag> : <div className="product-actions compact-actions"><button className="button button-ghost" onClick={() => setInvites(invites.filter((entry) => entry !== inviteEn))}>{t("Decline", "رفض")}</button><button className="button button-primary" onClick={() => setAccepted([...accepted, inviteEn])}>{t("Accept", "قبول")} <ArrowRight size={13} /></button></div>}</article>; })}</div>{invites.length === 0 && <div className="empty-state"><div className="complete-node"><Check size={22} /></div><h2>{t("Nothing waiting.", "لا شيء بانتظارك.")}</h2><p>{t("You're caught up.", "أنت على اطلاع بكل شيء.")}</p></div>}</ProductShell>;
}

export function BillingWorkspace() {
  const { t } = useLocale();
  const [subscriber, setSubscriber] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-access-tier") === "subscriber");
  const activateSubscriberPreview = () => { window.localStorage.setItem("asaasi-access-tier", "subscriber"); setSubscriber(true); };
  return <ProductShell title={t("Membership", "العضوية")} active="/dashboard/billing"><div className="product-page-heading compact"><div><SectionLabel>{t("Membership", "العضوية")} / {subscriber ? t("Member", "عضو") : t("Free Member", "عضو مجاني")}</SectionLabel><h1>{subscriber ? t("You're getting the full ecosystem.", "أنت تحصل على المنظومة كاملة.") : t("You're seeing the network. Upgrading gets you moving in it.", "أنت ترى الشبكة الآن. الترقية تجعلك تتحرك فيها.")}</h1><p>{t("Free access is real, no bait-and-switch. But every cap you've hit this month (one intro, three courses, no masterminds) disappears the moment you upgrade.", "الوصول المجاني حقيقي، بلا خداع. لكن كل حد وصلت إليه هذا الشهر (مقدمة واحدة، ثلاث دورات، بلا مجموعات إرشاد) يختفي بمجرد أن ترقي عضويتك.")}</p></div><SignalTag tone={subscriber ? "yellow" : "soft"}>{subscriber ? t("Member active", "العضوية نشطة") : t("Free Member", "عضو مجاني")}</SignalTag></div><div className="access-tier-grid"><section className="access-tier-card visitor"><span className="mono">01 / {t("VISITOR", "زائر")}</span><h2>{t("Look before you commit.", "اطلع قبل أن تلتزم.")}</h2><p>{t("Browse the directory, providers, events, and articles before creating an account.", "تصفح الدليل والمزودين والفعاليات والمقالات قبل إنشاء حساب.")}</p><span className="tier-price">$0</span></section><section className="access-tier-card free"><span className="mono">02 / {t("FREE MEMBER", "عضو مجاني")}</span><h2>{t("Make your first move.", "اتخذ خطوتك الأولى.")}</h2><p>{t("A real profile, one introduction, one open ask, enough to test whether this network is worth your time.", "ملف شخصي حقيقي، مقدمة واحدة، طلب مفتوح واحد، يكفي لاختبار ما إذا كانت هذه الشبكة تستحق وقتك.")}</p><ul><li><Check size={14} /> {t("Full profile and community posting", "ملف شخصي كامل ونشر في المجتمع")}</li><li><Check size={14} /> {t("One introduction request, one open network request", "طلب مقدمة واحد، وطلب شبكة مفتوح واحد")}</li><li><Check size={14} /> {t("Free events and 3 courses", "فعاليات مجانية و٣ دورات")}</li></ul><span className="tier-state">{subscriber ? t("Included beneath Member", "متضمن ضمن عضوية Member") : t("Your current access", "وصولك الحالي")}</span></section><section className={`access-tier-card subscriber ${subscriber ? "is-active" : ""}`}><span className="mono">03 / {t("MEMBER", "عضو")}</span><h2>{t("Stop rationing the network.", "توقف عن تقنين استخدام الشبكة.")}</h2><p>{t("Unlimited requests, the full library, masterminds matched to your stage, and 1:1 mentor time, the parts of ASaaSI that actually move a company forward.", "طلبات غير محدودة، والمكتبة كاملة، ومجموعات إرشاد مطابقة لمرحلتك، ووقت فردي مع مرشد، الأجزاء التي تحرك الشركة فعلا في أساسي.")}</p><ul><li><Check size={14} /> {t("Unlimited introduction and network requests", "طلبات مقدمات وشبكة غير محدودة")}</li><li><Check size={14} /> {t("Full course library, playbooks, and webinar replays", "مكتبة دورات كاملة، وأدلة عملية، وتسجيلات الندوات")}</li><li><Check size={14} /> {t("Masterminds, mentor booking, market reports, 5 team seats", "مجموعات إرشاد، وحجز مرشد، وتقارير السوق، و٥ مقاعد فريق")}</li></ul><button type="button" className="button button-primary" onClick={activateSubscriberPreview}>{subscriber ? <><Check size={14} /> {t("Member access active", "وصول العضو نشط")}</> : <>{t("Preview Member access", "معاينة وصول العضو")} <ArrowRight size={14} /></>}</button><small>{t("This frontend prototype changes access state only; it does not process a payment.", "هذا نموذج أولي للواجهة يغير حالة الوصول فقط؛ لا يعالج أي دفعة.")}</small></section></div><div className="billing-grid"><section className="billing-current panel-card"><SectionLabel>{t("Standalone purchases", "مشتريات مستقلة")}</SectionLabel><h2>{t("Pay for the specific work.", "ادفع مقابل العمل المحدد.")}</h2><p>{t("Paid workshops and provider engagements remain separate from membership. The access explanation stays close to each item before commitment.", "تبقى ورش العمل المدفوعة وتعاملات المزودين منفصلة عن العضوية. يبقى شرح الوصول قريبا من كل عنصر قبل الالتزام.")}</p><div className="billing-features"><span><Check size={14} /> {t("Workshops can be bought individually", "يمكن شراء ورش العمل بشكل فردي")}</span><span><Check size={14} /> {t("Provider work is scoped before purchase", "يُحدد نطاق عمل المزود قبل الشراء")}</span><span><Check size={14} /> {t("Membership is never required to hide the price", "العضوية ليست شرطا لإخفاء السعر أبدا")}</span></div></section><section className="billing-invoices panel-card"><SectionLabel>{t("Receipts", "الإيصالات")}</SectionLabel><h2>{t("Clear history.", "سجل واضح.")}</h2><div className="invoice-row"><span>{t("Member preview", "معاينة العضوية")} · {t("Aug 2026", "أغسطس ٢٠٢٦")}</span><strong>{subscriber ? t("Active", "نشط") : t("Not active", "غير نشط")}</strong><Download size={14} /></div><div className="invoice-row"><span>{t("Free Member", "عضو مجاني")} · {t("Jul 2026", "يوليو ٢٠٢٦")}</span><strong>$0</strong><Download size={14} /></div><button type="button" className="settings-link" onClick={() => window.alert(t("Payment management will be connected when checkout is enabled.", "ستُربط إدارة الدفع عند تفعيل الدفع."))}>{t("Payment settings", "إعدادات الدفع")} <ChevronRight size={15} /></button></section></div></ProductShell>;
}

export function AssessmentWorkspace() {
  const { t, formatNum } = useLocale();
  const { isAuthed } = useAuth();
  const [step, setStep] = useState(0);
  const [complete, setComplete] = useState(false);
  const prompts = [["Which decision feels most expensive right now?", "أي قرار يبدو الأكثر تكلفة الآن؟"], ["Where is the evidence still thin?", "أين لا تزال الأدلة ضعيفة؟"], ["What would make next month calmer?", "ما الذي سيجعل الشهر القادم أكثر هدوءا؟"]] as const;
  const options = [["I need sharper customer evidence", "أحتاج دليلا أوضح من العملاء"], ["I need a better pricing story", "أحتاج قصة تسعير أفضل"], ["I need the right person", "أحتاج الشخص المناسب"], ["I need to stop changing direction", "أحتاج التوقف عن تغيير الاتجاه"]] as const;
  const body = <div className="assessment-layout"><div className="product-page-heading compact"><SectionLabel>{t("Diagnostic", "التشخيص")} / {complete ? t("Complete", "مكتمل") : t(`Signal 0${step + 1}`, `الإشارة ٠${formatNum(step + 1)}`)}</SectionLabel><h1>{complete ? t("Your signal has a shape now.", "إشارتك أصبح لها شكل الآن.") : t(prompts[step][0], prompts[step][1])}</h1><p>{complete ? t("We'll use this to tune your events, people, and learning path.", "سنستخدم هذا لضبط فعالياتك وأشخاصك ومسار تعلمك.") : t("There is no right answer. Choose the truest one for this week.", "لا توجد إجابة صحيحة. اختر الأصدق لهذا الأسبوع.")}</p></div>{complete ? <div className="success-state"><div className="complete-node"><Check size={22} /></div><SectionLabel>{t("Founder signal ready", "إشارة المؤسس جاهزة")}</SectionLabel><h2>{t("Focus: finding a repeatable growth motion.", "التركيز: إيجاد حركة نمو قابلة للتكرار.")}</h2><p>{t("Your dashboard has been tuned around one pricing brief, a coach prompt, and two relevant introductions.", "ضُبطت لوحتك حول موجز تسعير واحد، وتوجيه من المرشد، ومقدمتين ذواتي صلة.")}</p>{isAuthed ? <Link href="/dashboard" className="button button-dark">{t("Enter dashboard", "ادخل إلى اللوحة")} <ArrowRight size={14} /></Link> : <><Link href="/signup" className="button button-dark">{t("Sign up to save your result", "سجل لحفظ نتيجتك")} <ArrowRight size={14} /></Link><p className="assessment-signup-note">{t("Free, and takes less than a minute — your next steps are waiting.", "مجاني، ويستغرق أقل من دقيقة، وخطواتك التالية في انتظارك.")}</p></>}</div> : <div className="assessment-options">{options.map((item) => <button className="tool-option" key={item[0]} onClick={() => step === prompts.length - 1 ? setComplete(true) : setStep(step + 1)}><span>{t(item[0], item[1])}</span><ArrowRight size={15} /></button>)}</div>}</div>;
  // The public /assessment route (the landing page's "Take the founder test" CTA) must stay
  // open to anonymous visitors - the quiz itself is the hook, signup only gates saving the
  // result. ProductShell force-redirects to /login when signed out, so only wrap authed
  // visitors in it (this also covers the /dashboard/assessment entry point); everyone else
  // gets the same content in a plain public shell, same pattern as RequestDetailPage's public branch.
  return isAuthed
    ? <ProductShell title={t("Founder diagnostic", "تشخيص المؤسس")} active="/dashboard/assessment">{body}</ProductShell>
    : <div className="missing-public"><div className="container detail-page">{body}</div></div>;
}

export function KnowledgeWorkspace() {
  const { t } = useLocale();
  const [enrolled, setEnrolled] = useState(false);
  return <ProductShell title={t("Knowledge", "المعرفة")} active="/knowledge"><div className="product-page-heading compact"><div><SectionLabel>{t("Knowledge / Stage 02", "المعرفة / المرحلة ٠٢")}</SectionLabel><h1>{t("Learn the thing that changes your next conversation.", "تعلم ما يغير محادثتك التالية.")}</h1><p>{t("Short courses, honest operator notes, and live sessions, organized around a founder decision.", "دورات قصيرة، وملاحظات صادقة من مشغلين، وجلسات مباشرة، منظمة حول قرار المؤسس.")}</p></div><SignalTag tone="soft">{enrolled ? t("Enrolled", "مسجَل") : t("2 paths available", "مساران متاحان")}</SignalTag></div><div className="knowledge-grid"><article className="knowledge-feature"><div><SignalTag>{t("Recommended", "موصى به")}</SignalTag><h2>{t("Find your first repeatable channel.", "اعثر على قناتك الأولى القابلة للتكرار.")}</h2><p>{t("Four stages from problem signal to a channel you can test without pretending it is a system yet.", "أربع مراحل من إشارة المشكلة إلى قناة يمكنك اختبارها دون التظاهر بأنها نظام بعد.")}</p></div><button className="button button-primary" onClick={() => setEnrolled(true)}>{enrolled ? t("Continue path", "تابع المسار") : t("Start learning path", "ابدأ مسار التعلم")} <ArrowRight size={14} /></button></article><div className="knowledge-list"><article><span className="mono">{t("Article / 07 min", "مقال / ٧ دقائق")}</span><h3>{t("Pricing is a promise, not a page.", "التسعير وعد، وليس صفحة.")}</h3><p>{t("How founders can talk about value before changing the tiers.", "كيف يمكن للمؤسسين الحديث عن القيمة قبل تغيير الفئات.")}</p><ArrowRight size={15} /></article><article><span className="mono">{t("Webinar / 45 min", "ندوة / ٤٥ دقيقة")}</span><h3>{t("Founder circles: the useful kind.", "دوائر المؤسسين: النوع المفيد.")}</h3><p>{t("A live discussion with operators from Cairo, Amman, and Dubai.", "نقاش مباشر مع مشغلين من القاهرة وعمان ودبي.")}</p><ArrowRight size={15} /></article><article><span className="mono">{t("Playbook / 12 min", "دليل عملي / ١٢ دقيقة")}</span><h3>{t("The first five customer conversations.", "أول خمس محادثات مع العملاء.")}</h3><p>{t("A practical script for finding the words worth keeping.", "نص عملي لإيجاد الكلمات التي تستحق الاحتفاظ بها.")}</p><ArrowRight size={15} /></article></div></div></ProductShell>;
}

export function ContactFlow() {
  const { t } = useLocale();
  const [sent, setSent] = useState(false);
  return <><PageIntro label={t("Support / Dispatch", "الدعم / إرسال")} title={t("Tell us what is blocking the next step.", "أخبرنا بما يعيق خطوتك التالية.")} copy={t("Choose the closest route and we'll keep the context with your request.", "اختر المسار الأقرب وسنحتفظ بالسياق مع طلبك.")} note={<SignalTag tone="soft">{t("Replies within 1-2 days", "ردود خلال يوم إلى يومين")}</SignalTag>} /><section className="section"><div className="container" style={{ maxWidth: 640 }}>{sent ? <div className="success-state public-success" role="status" aria-live="polite"><div className="complete-node"><Check size={22} /></div><SectionLabel>{t("Dispatch sent", "تم الإرسال")}</SectionLabel><h2>{t("Someone from ASaaSI will pick this up.", "سيتابع معك أحد فريق أساسي.")}</h2><p>{t("We'll reply by email and keep the thread here.", "سنرد عبر البريد الإلكتروني ونبقي المحادثة هنا.")}</p><button className="button button-ghost" onClick={() => setSent(false)}>{t("Send another message", "أرسل رسالة أخرى")}</button></div> : <div className="request-compose"><div className="request-types"><span className="mono">{t("I need help with", "أحتاج مساعدة في")}</span><button type="button" className="request-type active">{t("My account", "حسابي")} <ChevronRight size={14} /></button><button type="button" className="request-type">{t("A partnership", "شراكة")} <ChevronRight size={14} /></button><button type="button" className="request-type">{t("An event", "فعالية")} <ChevronRight size={14} /></button><button type="button" className="request-type">{t("Something else", "شيء آخر")} <ChevronRight size={14} /></button></div><form className="request-form" onSubmit={(event) => { event.preventDefault(); setSent(true); }}><SectionLabel>{t("Dispatch / New message", "إرسال / رسالة جديدة")}</SectionLabel><h2>{t("Give us the useful version.", "أعطنا النسخة المفيدة.")}</h2><label>{t("Subject", "الموضوع")}<input required placeholder={t("What should we help you unblock?", "بماذا نساعدك على التقدم؟")} /></label><label>{t("Context", "السياق")}<textarea required placeholder={t("Share the route, decision, or error you are seeing.", "شارك المسار أو القرار أو الخطأ الذي تراه.")} /></label><div className="form-footer"><span className="mono">{t("No ticket maze", "بلا متاهة تذاكر")}</span><button className="button button-primary" type="submit">{t("Send message", "أرسل الرسالة")} <ArrowRight size={14} /></button></div></form></div>}</div></section></>;
}

export { DashboardHome as Dashboard, LearnerWorkspace, CoachWorkspace, ProfileWorkspace, SavedWorkspace, SettingsWorkspace, NotificationsWorkspace };
